 for(const [lane,x,y,r] of [[0,x0,y0,r0],[1,x1,y1,r1]]){
  const length=Math.sqrt(x*x+y*y);scalar[0]=(length===0?0:(length-r)/length)*.5;
  actualBits[0]=bits(lane);
  if(Number.isNaN(scalar[0]))assert(Number.isNaN(actual[0]));else assert.equal(actualBits[0],expectedBits[0]);
  comparisons++;
 }
}
