function random(){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return seed>>>0;}
for(let i=0;i<500000;i++){
 for(let j=0;j<words.length;j++)words[j]=random();
 check(...values);check(values[0],values[1],values[2],values[0],values[1],values[2]);
}
